import{_ as a}from"./chunks/hamburger_menu.BLyto8gA.js";import{_ as i}from"./chunks/EN.P9aPnFBv.js";import{_ as o}from"./chunks/M-S-HDS-CF6.onaQ35vF.js";import{_ as t,o as n,c as s,a3 as r}from"./chunks/framework.g9mfNVRQ.js";const b=JSON.parse('{"title":"Follower CareLink","description":"","frontmatter":{"source_hash":"29d4533605","source_commit":"7a18e7c","i18n_outdated":true},"headers":[],"relativePath":"it/install/carelinkfollow.md","filePath":"it/install/carelinkfollow.md"}'),l={name:"it/install/carelinkfollow.md"};function p(c,e,d,m,u,v){return n(),s("div",null,[...e[0]||(e[0]=[r('<div class="admonition xdrip"><p class="admonition-title"><img src="'+a+'" style="zoom:75%;"></p><p> Impostazioni<br>  Dati Hardware di origine<br>   CareLink Follower</p></div><br><div class="warning custom-block"><p class="custom-block-title">Attenzione</p><p>I server CareLink sono soggetti a frequenti modifiche che possono rendere inutilizzabile la funzione.<br><strong>In caso di problemi usa l&#39;<a href="./download.html#pre-release">ultima pre-release</a>.</strong><br> Valuta di usare <a href="./companion.html">Companion App</a> sul telefono master e xDrip <a href="./xdripfollower.html">Sync</a> o Nightscout per condividere i dati.<br> L&#39;autenticazione dell&#39;app CarePartner è valida per 1 settimana: anche se xDrip non riesce a collegarsi a CareLink per qualche giorno (ad esempio per mancanza di connessione a internet), potrà rinnovare l&#39;accesso (aggiornare il token) automaticamente in background quando riesce di nuovo a collegarsi a CareLink, senza dover accedere di nuovo manualmente con il browser. Anche a questo processo di autenticazione si applica la restrizione sull&#39;account utente:<br><strong>per xDrip va usato un account follower dedicato: non puoi usare lo stesso follower per altre app o altri telefoni.</strong></p></div><br><p>Funziona anche con un CGM Simplera autonomo (usato senza un microinfusore collegato) che carica i dati su CareLink.</p><p>Seleziona il paese in cui hai registrato il tuo utente CareLink.</p><div class="admonition xdripitem"><p class="admonition-title">Paese CareLink</p><p> Seleziona il tuo paese CareLink.</p></div><p>Imposta il nome utente del paziente se usi un account care partner con più pazienti.</p><div class="admonition xdripitem"><p class="admonition-title">Nome Utente Paziente CareLink</p><p> Nome utente paziente CareLink (opzionale)</p></div><p>xDrip aprirà il sito di autenticazione CareLink: inserisci le tue credenziali per accedere.</p><div class="admonition xdripitem"><p class="admonition-title">Login</p><p> Accedi con il browser</p></div><p>Il periodo di grazia è un tempo di attesa aggiuntivo dopo la ricezione dell&#39;ultima lettura + 5 minuti.<br> Serve a evitare il blocco da parte del server se xDrip invia richieste troppo frequenti.</p><div class="admonition xdripitem"><p class="admonition-title">Periodo di grazia</p><p> Periodo di tolleranza per la richiesta di dati in secondi</p></div><p>L&#39;intervallo di richiesta dei dati mancanti è un tempo di attesa aggiuntivo dopo la ricezione dell&#39;ultima lettura + 5 minuti + periodo di grazia.<br> Serve a evitare il blocco da parte del server se xDrip invia richieste troppo frequenti.</p><div class="admonition xdripitem"><p class="admonition-title">Intervallo richiesta dati mancanti</p><p> Intervallo di richieste dopo dati mancanti, in minuti</p></div><br><h4 id="treatments" tabindex="-1">Trattamenti <a class="header-anchor" href="#treatments" aria-label="Permalink to &quot;Trattamenti {#treatments}&quot;">​</a></h4><p>Puoi scaricare i trattamenti e ricevere le notifiche.</p><div class="admonition xdripitem"><p class="admonition-title">Glicemia capillare <span class="symbol"><img src="'+i+'" style="zoom:75%;"></span></p><p> Scarica misure capillare da CareLink</p></div><div class="admonition xdripitem"><p class="admonition-title">Boli <span class="symbol"><img src="'+i+'" style="zoom:75%;"></span></p><p> Scarica boli da CareLink</p></div><div class="admonition xdripitem"><p class="admonition-title">Pasti <span class="symbol"><img src="'+i+'" style="zoom:75%;"></span></p><p> Scarica pasti da CareLink</p></div><div class="admonition xdripitem"><p class="admonition-title">Notifiche <span class="symbol"><img src="'+i+'" style="zoom:75%;"></span></p><p> Scarica le notifiche da CareLink</p></div><br><h4 id="status-line" tabindex="-1">Riga di stato <a class="header-anchor" href="#status-line" aria-label="Permalink to &quot;Riga di stato {#status-line}&quot;">​</a></h4><p>Lo stato del sensore e lo stato del microinfusore possono essere attivati nell&#39;opzione <a href="./../use/lesscommon.html#extra-status-line">Riga di stato extra</a>.</p><div class="admonition xdrip"><p class="admonition-title"><img src="'+a+'" style="zoom:75%;"></p><p> Impostazioni<br>   Impostazioni Meno Usate<br>   Riga di stato extra</p></div><div class="admonition xdripitem"><p class="admonition-title">Stato Esterno <span class="symbol"><img src="'+i+'" style="zoom:75%;"></span></p><p> Mostra lo stato di altre applicazioni come AndroidAPS</p></div><div class="admonition xdripitem"><p class="admonition-title">Stato del micro <span class="symbol"><img src="'+i+'" style="zoom:75%;"></span></p><p> Mostra informazioni sullo stato del micro se disponibile</p></div><p>Le informazioni del microinfusore (stato, basale) sono <u>visibili solo</u> nella riga di stato e <strong>non possono essere caricate su Nightscout/Tidepool</strong>.</p><img src="'+o+'" style="zoom:75%;"><br><p>Se non vedi dati e non compare alcun messaggio di errore, potrebbe essere necessario <a href="./../use/startsensor.html#followers-and-companion-apps">Inizializza Sensore</a>.</p><p><a href="https://github.com/NightscoutFoundation/xDrip/releases/tag/2026.11.21" target="_blank" rel="noreferrer"><em>Ultima modifica 23/11/2026</em></a></p>',33)])])}const _=t(l,[["render",p]]);export{b as __pageData,_ as default};
